from math import comb, factorial

def multinomial_pmf(counts, probs):
    """P(N_1 = counts[0], N_2 = counts[1], ...)."""
    n = sum(counts)
    orders = factorial(n)
    for c in counts:
        orders //= factorial(c)
    chance = 1.0      # product of p ** c
    for c, p in zip(counts, probs):
        chance *= p ** c
    return orders * chance

def nb_pmf(t, r, p):
    """P(T = t): the r-th success arrives on trial t."""
    return comb(t - 1, r - 1) * p ** r * (1 - p) ** (t - r)
